// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value, address target) public {
        vm.assume(value > 0 && value < address(c).balance + 1000 ether);
        Reverter reverter = new Reverter();
        vm.deal(address(c), value);
        vm.prank(c.owner());
        c.sendMoney(address(reverter), value, "");
        assertTrue(address(c).balance == value);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
